//! Replays `tests/fixtures/thread-search.jsonl`, generated by `tools/generate_thread_search_fixtures.mjs`
//! from the original: snippets, LIKE escaping, the input schema, the error envelope, and the ranked
//! search over rebuilt threads and messages.
use super::*;
use crate::persistence::write_projection;
use serde_json::{Value, json};
use t3_contracts::OrchestrationSearchThreadsInput;

fn rows(kind: &str) -> Vec<Value> {
    include_str!("../tests/fixtures/thread-search.jsonl")
        .lines()
        .map(|line| serde_json::from_str::<Value>(line).unwrap())
        .filter(|row| row["type"] == kind)
        .collect()
}

#[test]
fn snippets_and_escaping_match_the_original() {
    let snippets = rows("snippet");
    assert!(snippets.len() >= 35);
    for row in snippets {
        let (text, query) = (row["text"].as_str().unwrap(), row["query"].as_str().unwrap());
        assert_eq!(build_snippet(text, query), row["snippet"], "snippet of {} chars for {query:?}", text.len());
    }
    for row in rows("escape") {
        assert_eq!(escape_like_pattern(row["value"].as_str().unwrap()), row["escaped"].as_str().unwrap());
    }
}

#[test]
fn a_cut_through_a_surrogate_pair_leaves_a_replacement_character() {
    // The original leaves a lone surrogate here; a Rust string cannot hold one.
    for row in rows("snippet-split") {
        let snippet = build_snippet(row["text"].as_str().unwrap(), row["query"].as_str().unwrap());
        assert!(snippet.encode_utf16().count() <= SNIPPET_LIMIT + 2);
    }
    let text = format!("{}xneedle{}", "😀".repeat(80), "😀".repeat(80));
    let snippet = build_snippet(&text, "needle");
    assert!(snippet.starts_with("…\u{fffd}") && snippet.ends_with('…'), "{snippet:?}");
}

#[test]
fn input_decodes_like_the_original() {
    let inputs = rows("input");
    assert!(inputs.len() >= 30);
    for row in inputs {
        let decoded = serde_json::from_value::<OrchestrationSearchThreadsInput>(row["payload"].clone()).map(|input| serde_json::to_value(input).unwrap());
        match (decoded, row.get("ok").filter(|ok| !ok.is_null())) {
            (Ok(actual), Some(expected)) => assert_eq!(&actual, expected, "{}", row["payload"]),
            (Err(_), None) => {}
            (actual, expected) => panic!("{}: {actual:?} vs {expected:?}", row["payload"]),
        }
    }
}

#[test]
fn errors_use_the_original_envelope() {
    for row in rows("error") {
        let error = match row["operation"].as_str().unwrap() {
            "query" => SearchError::Query("boom".into()),
            _ => SearchError::Decode("boom".into()),
        };
        assert_eq!(error.wire(), row["wire"]);
    }
}

fn scenario_store(scenario: &Value) -> Store {
    let store = Store::memory().unwrap();
    store
        .transaction(|transaction| {
            for project in scenario["projects"].as_array().unwrap() {
                let deleted = if project["deleted"] == true { json!("2026-09-27T00:02:00.000Z") } else { Value::Null };
                write_projection(transaction, "project", project["id"].as_str().unwrap(), &json!({"projectId":project["id"],"title":project["id"],"workspaceRoot":format!("/work/{}", project["id"].as_str().unwrap()),"scripts":[],"createdAt":"2026-09-27T00:00:00.000Z","updatedAt":"2026-09-27T00:00:00.000Z","deletedAt":deleted}))?;
            }
            for thread in scenario["threads"].as_array().unwrap() {
                let id = thread["id"].as_str().unwrap();
                let messages: Vec<Value> = scenario["messages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .filter(|message| message["thread"] == thread["id"])
                    .map(|message| {
                        let text = if scenario["corruptText"] == message["id"] { json!(20260927) } else { message["text"].clone() };
                        json!({"id":message["id"],"threadId":id,"runId":null,"nodeId":null,"role":message["role"],"text":text,"attachments":[],"streaming":message["streaming"],"createdAt":message["createdAt"],"updatedAt":message["createdAt"]})
                    })
                    .collect();
                // The thread record keeps its own times; the projection's top-level `updatedAt`
                // is the time of the last event, which is what the original ranks by.
                write_projection(transaction, "thread", id, &json!({
                    "thread":{"id":id,"projectId":thread["project"],"title":id,"createdAt":thread["createdAt"],"updatedAt":thread["createdAt"],"archivedAt":thread["archivedAt"],"deletedAt":thread["deletedAt"]},
                    "updatedAt":thread["updatedAt"],"runs":[],"messages":messages,"turnItems":[],
                }))?;
            }
            Ok(())
        })
        .unwrap();
    store
}

#[test]
fn ranked_search_matches_the_original() {
    let scenarios = rows("search");
    assert!(scenarios.len() >= 7);
    for row in scenarios {
        let scenario = &row["scenario"];
        let name = scenario["name"].as_str().unwrap();
        let store = scenario_store(scenario);
        for result in row["results"].as_array().unwrap() {
            let input = &result["input"];
            let context = format!("{name}: {input}");
            let actual = search(&store, input["query"].as_str().unwrap(), input.get("limit").and_then(Value::as_u64).map(|limit| limit as u32));
            match (actual, result.get("matches"), result.get("error")) {
                (Ok(found), Some(expected), None) => {
                    let found: Vec<Value> = found.iter().map(|m| json!({"threadId":m.thread_id,"projectId":m.project_id,"source":m.source,"snippet":m.snippet,"messageCreatedAt":m.message_created_at})).collect();
                    assert_eq!(Value::Array(found), *expected, "{context}");
                }
                (Err(error), None, Some(operation)) => assert_eq!(error.operation(), operation, "{context}"),
                (actual, matches, error) => panic!("{context}: {actual:?} vs {matches:?} {error:?}"),
            }
        }
    }
}

#[test]
fn text_that_json_escapes_is_still_found() {
    // Queries with quotes, backslashes or non-ASCII skip the raw-JSON prefilter.
    let scenario = json!({
        "projects":[{"id":"p"}],
        "threads":[{"id":"t","project":"p","createdAt":"2026-09-27T00:00:00.000Z","updatedAt":"2026-09-27T00:01:00.000Z","archivedAt":null,"deletedAt":null}],
        "messages":[{"thread":"t","id":"m","role":"user","text":"say \"hi\" \\ there\nnext é line","createdAt":"2026-09-27T00:01:00.000Z","streaming":false}],
    });
    let store = scenario_store(&scenario);
    for query in ["\"hi\"", "\\ there", "say \"hi", "there\nnext", "é line", "NEXT", "hi\" \\", "say"] {
        assert_eq!(search(&store, query, None).unwrap().len(), 1, "{query:?}");
    }
    assert!(search(&store, "É LINE", None).unwrap().is_empty(), "non-ASCII case is not folded");
}
